33: export async function buildReport(
34:   root: string,
35:   sessionId: string,
36:   pgns: readonly string[],
37:   engine?: Evaluator,
38: ): Promise<Report | Refusal> {
39:   const meta = await readMeta(root, sessionId);
40:   await deleteReport(root, sessionId);
41:   const samples = await readSamples(root, sessionId);
42:   const refusal = gate(meta, samples, pgns);
43:   if (refusal) return refusal;
44: 
45:   const parsed = parsePgnBatch(pgns);
46:   if (!parsed.ok) {
47:     if (parsed.reason === 'order') {
48:       return { ok: false, reason: 'order', remedy: parsed.remedy };
49:     }
50:     if (parsed.reason === 'no_games') {
51:       return { ok: false, reason: 'no_games', remedy: parsed.remedy };
52:     }
53:     throw new Error(parsed.message);
54:   }
55: 
56:   const stop = meta.stopAnchor;
57:   if (!stop) {
58:     return { ok: false, reason: 'no_trace', remedy: 'Stop the session before building a report.' };
59:   }
60:   const aligned = alignGames(parsed.games, { startAnchor: meta.startAnchor, stopAnchor: stop }, samples);
61:   if (!aligned.ok) throw new Error(aligned.banner);
62: 
63:   const baseline = meta.baselineBpm ?? baselineFromSamples(samples, meta.startAnchor.monoUs)?.baselineBpm;
64:   if (baseline === undefined) throw new Error('No baseline was recorded, so bands were not computed.');
65: 
66:   const owned = engine === undefined;
67:   const scorer = engine ?? createEngine();
68:   try {
69:     const scoredMoves = await scoreAlignedMoves(aligned.games, aligned.moveTimes, samples, baseline, scorer);
70:     const summary = analyseMoves(scoredMoves.metrics);
71:     const claim = elevatedClaim(
72:       samples,
73:       meta.startAnchor.monoUs,
74:       stop.monoUs,
75:       baseline,
76:       scoredMoves.elevatedBlunderTimes,
77:     );
78:     const verdict = verdictLine(summary, {
79:       elevatedMinutes: claim?.elevatedMinutes,
80:       deltaBpm: claim?.deltaBpm,
81:       gapClause: gapClause(aligned.gaps),
82:     });
83:     const coverage = coverageFromSamples(samples, meta.startAnchor.monoUs, stop.monoUs);
84:     const first = aligned.games[0];
85:     const alignedIndices = new Set(aligned.games.map((entry) => entry.game.index));
86:     const blundersByGame = new Map<number, number>();
87:     for (const move of scoredMoves.timelineMoves) {
88:       if (move.blunder) blundersByGame.set(move.gameIndex, (blundersByGame.get(move.gameIndex) ?? 0) + 1);
89:     }
90:     const report = reportSchema.parse({
