98:       alignmentMode: first?.alignment.mode ?? 'inferred',
99:       toleranceSec: first?.alignment.toleranceSec ?? 0,
100:       ...(aligned.banner ? { banner: aligned.banner } : {}),
101:       games: parsed.games.map((game) => ({
102:         index: game.index,
103:         white: game.white,
104:         black: game.black,
105:         result: game.result,
106:         ending: game.ending,
107:         includeInStats: game.includeInStats,
108:         moveCount: game.moves.length,
109:         blunders: blundersByGame.get(game.index) ?? 0,
110:         aligned: alignedIndices.has(game.index),
111:         ...(game.timeControl !== undefined ? { timeControl: game.timeControl } : {}),
112:       })),
113:       timeline: {
114:         startUs: meta.startAnchor.monoUs,
115:         stopUs: stop.monoUs,
116:         baselineBpm: baseline,
117:         elevatedThresholdBpm: baseline + ELEVATED_MARGIN_BPM,
118:         samples: samples.filter(
