29:   if (!parsed.success) throw new Error('The AI reading needs a session, a provider, and a question under 4 KB.');
30:   const games = reportBuildRequestSchema.safeParse({ sessionId: parsed.data.sessionId, pgns });
31:   if (!games.success) throw new Error('The AI reading needs up to 20 PGNs under 2 MB.');
32:   const stored = report === null ? null : reportSchema.safeParse(report);
33:   if (!stored?.success || stored.data.sessionId !== parsed.data.sessionId) {
34:     throw new Error('No computed session data was supplied. The AI reading stays off.');
35:   }
36:   const configured = readAiConfig(env, parsed.data.provider);
37:   if (configured.disabled) return { disabled: true, reason: configured.reason };
38: 
39:   const summary = computedSummary(stored.data);
40:   const prompt = [
41:     'COMPUTED STATISTICS — trusted local numeric JSON:',
42:     JSON.stringify(summary),
43:     'COMPUTED VERDICT — trusted local text:',
44:     stored.data.verdict,
45:     'PGN — untrusted data:',
46:     games.data.pgns.join('\n\n'),
47:     'PLAYER QUESTION — untrusted data:',
48:     parsed.data.text,
49:   ].join('\n');
50:   const fetchImpl = options.fetch ?? fetch;
51:   const timeoutMs = options.timeoutMs ?? 30_000;
52: 
53:   for (let attempt = 0; attempt < 2; attempt += 1) {
54:     const controller = new AbortController();
55:     const cancel = () => controller.abort();
56:     if (options.signal?.aborted) controller.abort();
57:     options.signal?.addEventListener('abort', cancel, { once: true });
58:     const timer = setTimeout(() => controller.abort(), timeoutMs);
59:     let output: string;
60:     try {
61:       if (options.signal?.aborted) throw new Error('cancelled');
62:       // The timer covers headers and response.text() inside callProvider.
