69:       continue;
70:     } finally {
71:       clearTimeout(timer);
72:       options.signal?.removeEventListener('abort', cancel);
73:     }
74:     // Grounding is not a provider failure: never retry or disguise it as a network error.
75:     return {
76:       disabled: false,
