          calls += 1;
          return new Response('{}', { status: 500 });
        },
      },
    ),
    /Build the report again/,
  );
  assert.equal(calls, 0);
  assert.deepEqual((await readdir(path.join(root, 'sessions', meta.id))).filter((name) => name.endsWith('.tmp')), []);
});

